#include <string>
#include <vector>

std::string moveTo(int row, int col)
{
    return "\x1b[" + std::to_string(row + 1) + ";" + std::to_string(col + 1) + "H";
}

std::string colored(const std::string& text, int r, int g, int b)
{
    return "\x1b[38;2;" + std::to_string(r) + ";" + std::to_string(g) + ";" + std::to_string(b) + "m" + text + "\x1b[0m";
}

std::string frame(const std::vector<std::string>& map, int playerRow, int playerCol)
{
    std::string out{ "\x1b[H" };
    for (int row{ 0 }; row < static_cast<int>(map.size()); ++row)
    {
        std::string line{ map[static_cast<std::size_t>(row)] };
        if (row == playerRow && playerCol >= 0 && playerCol < static_cast<int>(line.size()))
            line[static_cast<std::size_t>(playerCol)] = '@';
        out += line;
        out += '\n';
    }
    return out;
}

