TEST("move elsewhere") { CHECK_EQ(moveTo(4, 19), std::string("\x1b[5;20H")); }
TEST("a colour") { CHECK_EQ(colored("Gold", 255, 200, 60), std::string("\x1b[38;2;255;200;60mGold\x1b[0m")); }
